document.querySelectorAll(`[data-tamm-next], [data-tamm-back]`).forEach(e=>{e.addEventListener(`click`,()=>{let t=document.querySelector(`.tamm-form-step:not([hidden])`);if(!t||e.hasAttribute(`data-tamm-next`)&&![...t.querySelectorAll(`input, select, textarea`)].every(e=>e.reportValidity()))return;let n=Number(t.dataset.tammStep),r=e.hasAttribute(`data-tamm-next`)?n+1:n-1;document.querySelectorAll(`.tamm-form-step`).forEach(e=>{e.hidden=Number(e.dataset.tammStep)!==r}),document.querySelectorAll(`[data-tamm-dot]`).forEach(e=>{e.classList.toggle(`is-active`,Number(e.dataset.tammDot)===r)})})}),document.querySelectorAll(`[data-tamm-day]`).forEach(e=>{e.addEventListener(`click`,()=>{let t=e.dataset.tammDay;document.querySelectorAll(`[data-tamm-day]`).forEach(t=>{t.setAttribute(`aria-selected`,String(t===e))}),document.querySelectorAll(`[data-tamm-programme]`).forEach(e=>{e.hidden=e.dataset.tammProgramme!==t})})});